 public sealed class PitchSegment{public double StartSeconds,EndSeconds,Midi;public int Target;public double Confidence;}
 public sealed class PitchAnalysis
 {
  public float[] Samples;public int Rate,Channels;public List<PitchSegment> Segments=new List<PitchSegment>();
  public static PitchAnalysis Analyze(string file,double offset,double duration){
   CachedAudio data=CachedAudio.Load(file);int first=(int)Math.Max(0,Math.Min(data.Frames,Math.Round(offset*data.Rate))),frames=(int)Math.Max(0,Math.Min(data.Frames-first,Math.Round(duration*data.Rate)));if(frames<512)throw new InvalidDataException("Audio selection is too short for pitch analysis.");
   var result=new PitchAnalysis{Rate=data.Rate,Channels=data.Channels,Samples=new float[frames*data.Channels]};Array.Copy(data.Samples,first*data.Channels,result.Samples,0,result.Samples.Length);
   int decimate=Math.Max(1,data.Rate/12000);double rate=data.Rate/(double)decimate;float[] mono=new float[frames/decimate];for(int i=0;i<mono.Length;i++){double v=0;for(int d=0;d<decimate;d++)for(int c=0;c<data.Channels;c++)v+=result.Samples[(i*decimate+d)*data.Channels+c];mono[i]=(float)(v/(data.Channels*decimate));}
   int min=(int)(rate/1100),max=(int)(rate/55),window=Math.Max(512,max*2),hop=128;PitchSegment last=null;
   for(int at=0;at+window+max<mono.Length;at+=hop){double energy=0;for(int i=0;i<window;i++)energy+=mono[at+i]*mono[at+i];if(energy/window<0.000009){last=null;continue;}double[] diff=new double[max+1];double running=0;int chosen=-1;for(int lag=1;lag<=max;lag++){double sum=0;for(int i=0;i<window;i++){double d=mono[at+i]-mono[at+i+lag];sum+=d*d;}running+=sum;diff[lag]=running>0?sum*lag/running:1;if(lag>min+1&&chosen<0&&diff[lag-1]<.16&&diff[lag]>diff[lag-1])chosen=lag-1;}
    if(chosen<0){last=null;continue;}double tau=chosen;if(chosen>1&&chosen<max){double a=diff[chosen-1],b=diff[chosen],c=diff[chosen+1],den=a-2*b+c;if(Math.Abs(den)>1e-12)tau+=(a-c)/(2*den);}
    double midi=69+12*Math.Log(rate/tau/440,2);if(midi<30||midi>100){last=null;continue;}double time=(at+window/2)/rate,confidence=1-diff[chosen];
    if(last!=null&&Math.Abs(last.Midi-midi)<.65&&time-last.EndSeconds<.04){last.EndSeconds=Math.Min(frames/(double)data.Rate,time+hop/rate);last.Midi=last.Midi*.8+midi*.2;last.Target=(int)Math.Round(last.Midi);last.Confidence=(last.Confidence+confidence)/2;}else{last=new PitchSegment{StartSeconds=Math.Max(0,time-window/(2*rate)),EndSeconds=time+hop/rate,Midi=midi,Target=(int)Math.Round(midi),Confidence=confidence};result.Segments.Add(last);}
   }
   result.Segments.RemoveAll(s=>s.EndSeconds-s.StartSeconds<.055);return result;
  }
  public float[] Render(){
   float[] result=(float[])Samples.Clone();int frames=Samples.Length/Channels;
   foreach(var segment in Segments){double ratio=Math.Pow(2,(segment.Target-segment.Midi)/12.0);if(Math.Abs(ratio-1)<.0001)continue;double frequency=440*Math.Pow(2,(segment.Midi-69)/12);int period=Math.Max(8,(int)Math.Round(Rate/frequency)),start=Math.Max(period,(int)(segment.StartSeconds*Rate)),end=Math.Min(frames-period,(int)(segment.EndSeconds*Rate));if(end-start<period*3)continue;
    var marks=new List<int>();int expected=start;while(expected<end){int best=expected;float max=Single.MinValue;for(int i=Math.Max(period,expected-period/4);i<=Math.Min(frames-period-1,expected+period/4);i++){float v=0;for(int c=0;c<Channels;c++)v+=Samples[i*Channels+c];if(v>max){max=v;best=i;}}if(marks.Count>0&&best<=marks[marks.Count-1])best=marks[marks.Count-1]+period;marks.Add(best);expected=best+period;}
    double[] weights=new double[end-start];double[] output=new double[(end-start)*Channels];double spacing=period/ratio;
    for(double destination=start;destination<end;destination+=spacing){int mark=marks[Math.Min(marks.Count-1,Math.Max(0,(int)Math.Round((destination-start)/period)))],center=(int)Math.Round(destination);for(int j=-period;j<=period;j++){int dest=center+j,source=mark+j;if(dest<start||dest>=end||source<0||source>=frames)continue;double weight=.5+.5*Math.Cos(Math.PI*j/period);weights[dest-start]+=weight;for(int c=0;c<Channels;c++)output[(dest-start)*Channels+c]+=Samples[source*Channels+c]*weight;}}
    int fade=Math.Min(Rate/100,(end-start)/4);for(int i=start;i<end;i++){double w=weights[i-start];if(w<.00001)continue;double blend=Math.Min(1,Math.Min((i-start)/(double)Math.Max(1,fade),(end-1-i)/(double)Math.Max(1,fade)));for(int c=0;c<Channels;c++)result[i*Channels+c]=(float)(Samples[i*Channels+c]*(1-blend)+output[(i-start)*Channels+c]/w*blend);}
   }return result;
  }
  public void Save(string path){float[] samples=Render();using(var w=new ExportWaveWriter(path,Rate,Channels,24,false))w.Write(samples,0,samples.Length);}
 }
 public sealed class SlopPitchEditor:ScaledCanvas {
  private double _tempo=120,_sourceTempo=120,_grid=.25,_amount=1;private Track _track;private Region _region;private PitchAnalysis _analysis;private TimingAnalysis _timing;private List<TimingMarker> _map;private string _error,_contentKey;private bool _busy,_timingMode;private PitchSegment _drag;private TimingMarker _dragTiming;private int _dragY,_dragPitch;public event Action<string> Baked;public string ModeName{get{return _timingMode?"Timing":"Pitch";}}
  public SlopPitchEditor(){Dock=DockStyle.Fill;DoubleBuffered=true;BackColor=EditorInk.Ground;Font=new Font("Segoe UI",8.5f);}
  public void SetContent(Track track,Region region,double tempo){_tempo=tempo;string key=region==null?null:region.Id+"|"+region.MediaPath+"|"+region.AudioOffsetSeconds+"|"+region.LengthBeats;_track=track;_region=region;if(key!=_contentKey){_analysis=null;_timing=null;_map=null;_error=null;_sourceTempo=tempo;_contentKey=key;}Invalidate();}
  private void Remap(){if(_timing!=null)_map=_timing.Map(_sourceTempo,_tempo,_grid,_amount);Invalidate();}
  private void Analyze(){if(_busy||_track==null||_track.Type!=TrackType.Audio||_region==null||String.IsNullOrEmpty(_region.MediaPath))return;string key=_contentKey,file=_region.MediaPath;double offset=_region.AudioOffsetSeconds,duration=Math.Min(120,_region.LengthBeats*60/_tempo);bool timing=_timingMode;_busy=true;_error=null;Invalidate();Task.Factory.StartNew(delegate{PitchAnalysis pitch=null;TimingAnalysis time=null;Exception error=null;try{double seconds=Math.Min(duration,WaveAudio.Inspect(file).DurationSeconds-offset);if(timing)time=TimingAnalysis.Analyze(file,offset,seconds);else pitch=PitchAnalysis.Analyze(file,offset,seconds);}catch(Exception ex){error=ex;}if(IsDisposed)return;try{BeginInvoke((Action)delegate{_busy=false;if(_contentKey==key){if(timing){_timing=time;if(time!=null){_sourceTempo=time.Confidence>.25?time.DetectedTempo:_tempo;Remap();}}else _analysis=pitch;_error=error==null?(timing?(time.Markers.Count<2?"Few transients detected. Set Source BPM manually.":null):(pitch.Segments.Count==0?"No reliable monophonic pitch detected.":null)):error.Message;}Invalidate();});}catch(InvalidOperationException){}});}
  private void RenderTake(){if(_busy||(_timingMode?_timing==null:_analysis==null))return;using(var dialog=new SaveFileDialog{Filter="WAV audio|*.wav",FileName="Slop "+ModeName+" Take.wav"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;string path=dialog.FileName,key=_contentKey;var timing=_timing;var map=_map==null?null:_map.Select(m=>new TimingMarker{SourceSeconds=m.SourceSeconds,TargetSeconds=m.TargetSeconds,Strength=m.Strength}).ToList();var pitch=_analysis;bool mode=_timingMode;_busy=true;Invalidate();Task.Factory.StartNew(delegate{Exception error=null;string temporary=path+"."+Guid.NewGuid().ToString("N")+".wav";try{if(mode)timing.Save(temporary,map);else pitch.Save(temporary);if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);}catch(Exception ex){error=ex;}finally{try{if(File.Exists(temporary))File.Delete(temporary);}catch{}}if(IsDisposed)return;try{BeginInvoke((Action)delegate{_busy=false;_error=error==null?null:error.Message;if(error==null&&_contentKey==key&&Baked!=null)Baked(path);Invalidate();});}catch(InvalidOperationException){}});}}
  private void Button(Graphics g,string text,Rectangle rect,bool selected){StudioDraw.Box(g,rect,selected?Color.FromArgb(49,129,190):Color.FromArgb(76,77,79),selected?Color.FromArgb(37,105,161):Color.FromArgb(60,61,63),3);StudioDraw.Label(g,text,Font,rect,Color.Gainsboro,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
  protected override void OnPaint(PaintEventArgs e){PreparePaint(e);base.OnPaint(e);var g=e.Graphics;g.Clear(BackColor);StudioDraw.Label(g,"Waveform Editor",Font,new Rectangle(12,3,115,26),EditorInk.Text,TextFormatFlags.VerticalCenter);Button(g,"Pitch",new Rectangle(140,4,63,24),!_timingMode);Button(g,"Timing",new Rectangle(208,4,70,24),_timingMode);Button(g,"Analyze",new Rectangle(Width-204,4,90,24),false);Button(g,"Render to Take",new Rectangle(Width-111,4,102,24),false);int header=_timingMode?75:45;
   if(_timingMode){Button(g,UiText.Translate("Source BPM")+" "+_sourceTempo.ToString("0.00"),new Rectangle(12,37,154,25),false);Button(g,UiText.Translate("Grid")+" 1/"+(4/_grid).ToString("0"),new Rectangle(174,37,112,25),false);Button(g,UiText.Translate("Strength")+" "+(_amount*100).ToString("0")+"%",new Rectangle(294,37,135,25),false);StudioDraw.Label(g,"→ "+_tempo.ToString("0.00")+" BPM  ·  "+(_timing==null?UiText.Translate("Transient analysis / pitch-preserving stretch"):UiText.Translate("Detection confidence")+" "+(_timing.Confidence*100).ToString("0")+"%"),Font,new Rectangle(440,37,Math.Max(1,Width-450),25),Color.Silver,TextFormatFlags.VerticalCenter);}
   if(_busy){StudioDraw.Label(g,"Processing actual audio…",Font,new Rectangle(14,header+10,Width-28,35),Color.Silver,TextFormatFlags.VerticalCenter);return;}
   if(_timingMode){DrawTiming(g,header);return;}if(_analysis==null){StudioDraw.Label(g,_error??"Select an audio region and choose Analyze. Analysis is limited to 120 seconds per selection.",Font,new Rectangle(14,header+10,Width-28,40),Color.Silver,TextFormatFlags.VerticalCenter);return;}double duration=_analysis.Samples.Length/(double)(_analysis.Rate*_analysis.Channels);const int min=36,max=88;for(int note=min;note<=max;note++){float y=header+(max-note)/(float)(max-min)*Math.Max(30,Height-header-15);using(var p=new Pen(note%12==0?Color.FromArgb(90,92,94):EditorInk.Grid))g.DrawLine(p,44,y,Width,y);if(note%12==0)StudioDraw.Label(g,"C"+(note/12-1),Font,new Rectangle(2,(int)y-10,40,20),Color.Silver,TextFormatFlags.VerticalCenter);}foreach(var segment in _analysis.Segments){float x=46+(float)(segment.StartSeconds/duration*(Width-60)),w=Math.Max(4,(float)((segment.EndSeconds-segment.StartSeconds)/duration*(Width-60))),y=header+(max-segment.Target)/(float)(max-min)*Math.Max(30,Height-header-15);using(var b=new SolidBrush(Color.FromArgb(66,166,207)))g.FillRectangle(b,x,y-4,w,8);}}
  private void DrawTiming(Graphics g,int header){if(_timing==null){StudioDraw.Label(g,_error??"Select audio, analyze transients, review Source BPM, then render a new take.",Font,new Rectangle(14,header+10,Width-28,40),Color.Silver,TextFormatFlags.VerticalCenter);return;}double duration=Math.Max(_timing.Duration,_map.Last().TargetSeconds);int left=16,w=Math.Max(1,Width-32),h=Math.Max(30,Height-header-35),middle=header+h/2;using(var p=new Pen(EditorInk.Grid))for(double beat=0;beat*60/_tempo<duration;beat+=_grid){int x=left+(int)(beat*60/_tempo/duration*w);g.DrawLine(p,x,header,x,header+h);}using(var p=new Pen(Color.FromArgb(88,164,178))){int frames=_timing.Samples.Length/_timing.Channels;for(int x=0;x<w;x++){int a=(int)(x/(double)w*duration*_timing.Rate),b=Math.Min(frames,(int)((x+1)/(double)w*duration*_timing.Rate));float peak=0;for(int f=a;f<b;f+=Math.Max(1,(b-a)/12))for(int c=0;c<_timing.Channels;c++)peak=Math.Max(peak,Math.Abs(_timing.Samples[f*_timing.Channels+c]));g.DrawLine(p,left+x,middle-peak*h*.42f,left+x,middle+peak*h*.42f);}}foreach(var marker in _map.Skip(1).Take(_map.Count-2)){float source=left+(float)(marker.SourceSeconds/duration*w),target=left+(float)(marker.TargetSeconds/duration*w);using(var p=new Pen(Color.FromArgb(242,179,72),2)){g.DrawLine(p,target,header,target,header+h);g.DrawLine(p,source,middle,target,header+8);}using(var b=new SolidBrush(Color.FromArgb(242,179,72)))g.FillPolygon(b,new[]{new PointF(target-4,header),new PointF(target+4,header),new PointF(target,header+8)});}StudioDraw.Label(g,_error??"Drag timing markers to refine. Render creates a new take and preserves the original for Undo.",Font,new Rectangle(14,Height-27,Width-28,23),Color.Silver,TextFormatFlags.VerticalCenter);}
  protected override void OnMouseDown(MouseEventArgs e){e=LogicalMouse(e);base.OnMouseDown(e);if(e.Button!=MouseButtons.Left||_busy)return;if(e.Y<32){if(e.X>=Width-111)RenderTake();else if(e.X>=Width-204)Analyze();else if(e.X>=140&&e.X<203){_timingMode=false;Invalidate();}else if(e.X>=208&&e.X<278){_timingMode=true;Invalidate();}return;}
   if(_timingMode){if(e.Y<70){if(e.X>=12&&e.X<166){double? bpm=ValuePrompt.Ask(FindForm(),"Source BPM",_sourceTempo,20,400,2);if(bpm.HasValue){_sourceTempo=bpm.Value;Remap();}}else if(e.X>=174&&e.X<286){_grid=_grid==1?.5:_grid==.5?.25:_grid==.25?.125:1;Remap();}else if(e.X>=294&&e.X<429){double? amount=ValuePrompt.Ask(FindForm(),"Strength",_amount*100,0,100,0);if(amount.HasValue){_amount=amount.Value/100;Remap();}}return;}if(_timing==null)return;double duration=Math.Max(_timing.Duration,_map.Last().TargetSeconds),time=(e.X-16)/(double)Math.Max(1,Width-32)*duration;_dragTiming=_map.Skip(1).Take(_map.Count-2).OrderBy(m=>Math.Abs(m.TargetSeconds-time)).FirstOrDefault();if(_dragTiming!=null&&Math.Abs(_dragTiming.TargetSeconds-time)/duration*(Width-32)>9)_dragTiming=null;if(_dragTiming!=null)Capture=true;return;}
   if(_analysis==null)return;double seconds=_analysis.Samples.Length/(double)(_analysis.Rate*_analysis.Channels),at=(e.X-46)/(double)Math.Max(1,Width-60)*seconds;_drag=_analysis.Segments.Find(p=>at>=p.StartSeconds&&at<=p.EndSeconds);if(_drag!=null){_dragY=e.Y;_dragPitch=_drag.Target;Capture=true;}}
  protected override void OnMouseMove(MouseEventArgs e){e=LogicalMouse(e);base.OnMouseMove(e);if(_dragTiming!=null){int index=_map.IndexOf(_dragTiming);double duration=Math.Max(_timing.Duration,_map.Last().TargetSeconds),time=(e.X-16)/(double)Math.Max(1,Width-32)*duration;_dragTiming.TargetSeconds=Math.Max(_map[index-1].TargetSeconds+.002,Math.Min(_map[index+1].TargetSeconds-.002,time));Invalidate();}else if(_drag!=null){_drag.Target=Math.Max(24,Math.Min(108,_dragPitch+(int)Math.Round((_dragY-e.Y)*52.0/Math.Max(30,Height-60))));Invalidate();}}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);_drag=null;_dragTiming=null;Capture=false;}
 }
}
